async function insertSecurityIncident(db3, incident) {
  await db3.insert(securityIncidents).values({
    entityId: incident.entityId,
    type: incident.type,
    severity: incident.severity,
    context: incident.context ?? {},
    details: incident.details ?? {},
    handled: "pending"
  });
}
async function getRecentIncidents(db3, roomId, hours = 24) {
  const cutoff = new Date(Date.now() - hours * 60 * 60 * 1000);
  const rows = await db3.select().from(securityIncidents).where(gt(securityIncidents.timestamp, cutoff)).orderBy(desc(securityIncidents.timestamp)).limit(100);
  if (roomId) {
    return rows.filter((row) => {
      const ctx = row.context;
      return ctx?.roomId === roomId;
    });
  }
  return rows;
}
async function insertTrustEvidence(db3, evidence) {
  await db3.insert(trustEvidence).values({
    targetEntityId: evidence.targetEntityId,
    sourceEntityId: evidence.sourceEntityId,
    evaluatorId: evidence.evaluatorId,
    type: evidence.type,
    impact: evidence.impact,
    weight: evidence.weight ?? 1,
    description: evidence.description ?? "",
    verified: evidence.verified ?? false,
    context: evidence.context ?? {}
  });
}
