init_types4();
init_utils();
function resolveWorldId(worldId, messageServerId, agentId) {
  if (worldId)
    return worldId;
  if (messageServerId)
    return stringToUuid(`${messageServerId}:${agentId}`);
  throw new Error("worldId or messageServerId is required");
}
async function ensureConnections(adapter, params) {
  const { agentId, connections } = params;
  if (!connections.length)
    return { createdRoomParticipants: 0 };
  const entityMap = new Map;
  const worldMap = new Map;
  const roomMap = new Map;
  const roomParticipants = new Map;
  for (const c2 of connections) {
    const worldId = resolveWorldId(c2.worldId, c2.messageServerId, agentId);
    const names = [c2.name, c2.userName].filter(Boolean);
    const source = c2.source || "default";
    const entityKey = c2.entityId;
    if (!entityMap.has(entityKey)) {
      entityMap.set(entityKey, {
        entityId: c2.entityId,
        names: [],
        metadata: {},
        agentId
      });
    }
    const ent = entityMap.get(entityKey);
    if (!ent) {
      continue;
    }
    ent.names = [...new Set([...ent.names, ...names])].filter(Boolean);
    ent.metadata[source] = {
      id: c2.userId,
      name: c2.name,
      userName: c2.userName
    };
    const world = {
      id: worldId,
      name: c2.worldName ? c2.worldName : c2.messageServerId ? `World for server ${c2.messageServerId}` : `World for room ${c2.roomId}`,
      agentId,
      messageServerId: c2.messageServerId,
      metadata: c2.metadata
    };
    worldMap.set(worldId, world);
    const roomType = typeof c2.type === "string" && Object.values(ChannelType).includes(c2.type) ? c2.type : ChannelType.DM;
    const room = {
      id: c2.roomId,
      name: c2.roomName || c2.name || "default",
      source,
      type: roomType,
      channelId: c2.channelId ?? c2.roomId,
      messageServerId: c2.messageServerId,
      worldId
    };
    roomMap.set(c2.roomId, room);
    if (!roomParticipants.has(c2.roomId)) {
      roomParticipants.set(c2.roomId, new Set);
    }
    const participants = roomParticipants.get(c2.roomId);
    if (!participants) {
      continue;
    }
    participants.add(c2.entityId);
    participants.add(agentId);
  }
  const entityIds = [...entityMap.keys()];
  const existingEntities = entityIds.length > 0 ? await adapter.getEntitiesByIds(entityIds) : [];
  const existingByKey = new Map(existingEntities.map((e) => [e.id, e]));
  const entities = [];
  for (const [, v2] of entityMap) {
    const existing = existingByKey.get(v2.entityId) ?? null;
    const names = existing ? [...new Set([...existing.names || [], ...v2.names])].filter(Boolean) : v2.names;
    const metadata = existing ? { ...existing.metadata, ...v2.metadata } : v2.metadata;
    entities.push({
      id: v2.entityId,
      names,
      metadata,
      agentId: v2.agentId
    });
  }
  if (entities.length)
    await adapter.upsertEntities(entities);
  const worlds = [...worldMap.values()].map((w) => ({
    ...w,
    agentId
  }));
  if (worlds.length)
    await adapter.upsertWorlds(worlds);
  const rooms = [...roomMap.values()].map((r) => ({
    ...r,
    agentId
  }));
  if (rooms.length)
    await adapter.upsertRooms(rooms);
  let createdRoomParticipants = 0;
  for (const [roomId, entityIdsSet] of roomParticipants) {
    const currentResult = await adapter.getParticipantsForRooms([
      roomId
    ]);
    const current = currentResult[0]?.entityIds ?? [];
    const missing = [...entityIdsSet].filter((id) => !current.includes(id));
    if (missing.length) {
      await adapter.createRoomParticipants(missing, roomId);
      createdRoomParticipants += missing.length;
    }
  }
  return { createdRoomParticipants };
}
async function ensureConnection(adapter, params) {
  if (!params.source) {
    throw new Error("Source is required for ensureConnection");
  }
  const worldId = resolveWorldId(params.worldId, params.messageServerId, params.agentId);
  return ensureConnections(adapter, {
    agentId: params.agentId,
    connections: [{ ...params, worldId }]
  });
}

