// src/providers/recent-errors.ts
init_logger2();
var MAX_RECENT_ERRORS = 5;
var ERROR_MAX_AGE_MS = 30 * 60 * 1000;
var MAX_CONTEXT_CHARS = 400;
var EMPTY_RESULT3 = {
  data: { recentErrors: [] },
  values: { recentErrors: "" },
  text: ""
};
function serializeContext(context) {
  if (!context || Object.keys(context).length === 0)
    return;
  let text;
  try {
    text = JSON.stringify(context);
  } catch {
    return;
  }
  return text.length > MAX_CONTEXT_CHARS ? `${text.slice(0, MAX_CONTEXT_CHARS)}…` : text;
}
function selectRecentErrors(entries, now2) {
  const newestByCode = new Map;
  for (const entry of entries) {
    if (now2 - entry.at > ERROR_MAX_AGE_MS)
      continue;
    const existing = newestByCode.get(entry.code);
    if (!existing || entry.at >= existing.at) {
      newestByCode.set(entry.code, entry);
    }
  }
  return [...newestByCode.values()].sort((a3, b4) => b4.at - a3.at).slice(0, MAX_RECENT_ERRORS);
}
function renderText(selected) {
  const lines = selected.map((entry) => {
    const ctx = serializeContext(entry.context);
    const suffix = ctx ? ` — ${ctx}` : "";
    return `- [${entry.scope}] ${entry.code}: ${entry.message}${suffix}`;
  });
  return `## Recent runtime errors

The following failures were reported outside the normal action flow:

${lines.join(`
`)}

If a failure looks actionable, attempt to resolve it (re-run the operation, reconfigure the failing feature, or disable it). If it looks systemic or you cannot resolve it, tell the owner.`;
}
var recentErrorsProvider = {
  name: "RECENT_ERRORS",
  description: "Recent runtime failures reported outside the action path (deduped by code)",
  dynamic: true,
  alwaysInResponseState: true,
  get: async (runtime2, _message, _state) => {
    const entries = runtime2.getRecentReportedErrors();
    if (entries.length === 0)
      return EMPTY_RESULT3;
    const selected = selectRecentErrors(entries, Date.now());
    if (selected.length === 0)
      return EMPTY_RESULT3;
    const text = renderText(selected);
    logger.debug({ src: "agent", count: selected.length }, "[RecentErrorsProvider] Surfacing recent reported errors");
    return {
      data: { recentErrors: selected },
      values: { recentErrors: text },
      text
    };
  }
};

