// src/features/advanced-capabilities/experience/providers/experienceProvider.ts
var spec17 = requireProviderSpec2("experienceProvider");
var MAX_RELEVANT_EXPERIENCES = 7;
var experienceProvider = {
  name: spec17.name,
  description: "Provides relevant past experiences and learnings for the current context",
  dynamic: true,
  contexts: ["general"],
  contextGate: { anyOf: ["general"] },
  cacheStable: false,
  cacheScope: "turn",
  roleGate: { minRole: "USER" },
  async get(runtime2, message, _state) {
    try {
      const experienceService = runtime2.getService("EXPERIENCE");
      if (!experienceService) {
        return { text: "", data: {}, values: {} };
      }
      const messageText2 = message.content.text || "";
      if (messageText2.length < 10) {
        return { text: "", data: {}, values: {} };
      }
      const semanticExperiences = await experienceService.queryExperiences({
        query: messageText2,
        limit: 5,
        minConfidence: 0.6,
        minImportance: 0.5,
        includeRelated: true
      });
      const topExperiences = await experienceService.listExperiences({
        limit: 3,
        minConfidence: 0.7,
        minImportance: 0.7
      });
      const relevantExperiences = [
        ...new Map([...semanticExperiences, ...topExperiences].map((experience) => [
          experience.id,
          experience
        ])).values()
      ].slice(0, MAX_RELEVANT_EXPERIENCES);
      if (relevantExperiences.length === 0) {
        return { text: "", data: {}, values: {} };
      }
      const experienceText = relevantExperiences.map((experience, index2) => formatExperienceForPrompt(experience, index2)).join(`

`);
      const contextText = `[RELEVANT EXPERIENCES]
${experienceText}
[/RELEVANT EXPERIENCES]`;
      logger.debug(`[experienceProvider] Injecting ${relevantExperiences.length} relevant experiences`);
      return {
        text: contextText,
        data: {
          experiences: relevantExperiences,
          count: relevantExperiences.length
        },
        values: {
          experienceCount: relevantExperiences.length.toString()
        }
      };
    } catch (error) {
      return {
        text: "",
        data: {
          experiences: [],
          count: 0,
          error: error instanceof Error ? error.message : String(error)
        },
        values: { experienceCount: "0" }
      };
    }
  }
};

