    cloudEnabled: runtimeSetting(runtime2, "ELIZAOS_CLOUD_ENABLED"),
    cloudBaseUrl: runtimeSetting(runtime2, "ELIZAOS_CLOUD_REQUEST_BASE_URL") ?? runtimeSetting(runtime2, "ELIZAOS_CLOUD_BASE_URL"),
    tunnelActive,
