// src/features/secrets/providers/secrets-status.ts
var MAX_SECRET_KEYS = 20;
var secretsStatusProvider = {
  name: "SECRETS_STATUS",
  description: "Provides information about configured secrets and their status",
  dynamic: true,
  contexts: ["secrets", "settings"],
  contextGate: { anyOf: ["secrets", "settings"] },
  cacheStable: false,
  cacheScope: "turn",
  roleGate: { minRole: "ADMIN" },
  get: async (runtime2, _message, _state) => {
    const secretsService = runtime2.getService(SECRETS_SERVICE_TYPE);
    if (!secretsService) {
      return { text: "" };
    }
    try {
      const globalSecrets = await secretsService.list({
        level: "global",
        agentId: runtime2.agentId,
        requesterId: runtime2.agentId
      });
      const secretKeys = Object.keys(globalSecrets);
      if (secretKeys.length === 0) {
        return {
          text: `[Secrets Status]
No secrets are currently configured. The agent may need API keys or other credentials to access certain services.`
        };
      }
      const valid = [];
      const missing = [];
      const invalid = [];
      for (const [key, config] of Object.entries(globalSecrets)) {
        switch (config.status) {
          case "valid":
            valid.push(key);
            break;
          case "missing":
            missing.push(key);
            break;
          case "invalid":
          case "expired":
          case "revoked":
            invalid.push(key);
            break;
          default:
            valid.push(key);
        }
      }
      const lines = ["[Secrets Status]"];
      if (valid.length > 0) {
        lines.push(`Configured secrets: ${valid.join(", ")}`);
      }
      if (invalid.length > 0) {
        lines.push(`Invalid/expired secrets: ${invalid.join(", ")}`);
      }
      if (missing.length > 0) {
        lines.push(`Missing required secrets: ${missing.join(", ")}`);
      }
      const activatorService = runtime2.getService(PLUGIN_ACTIVATOR_SERVICE_TYPE);
      if (activatorService) {
        const pendingPlugins = activatorService.getPendingPlugins();
        if (pendingPlugins.length > 0) {
          lines.push(`Plugins waiting for secrets: ${pendingPlugins.join(", ")}`);
          const requiredSecrets = activatorService.getRequiredSecrets();
          if (requiredSecrets.size > 0) {
            lines.push(`Secrets needed for pending plugins: ${Array.from(requiredSecrets).slice(0, MAX_SECRET_KEYS).join(", ")}`);
          }
        }
      }
      return {
        text: lines.join(`
`),
        data: {
          configuredCount: valid.length,
          invalidCount: invalid.length,
          missingCount: missing.length,
          configuredKeys: valid.slice(0, MAX_SECRET_KEYS),
          invalidKeys: invalid.slice(0, MAX_SECRET_KEYS),
          missingKeys: missing.slice(0, MAX_SECRET_KEYS)
        },
        values: {
          configuredSecrets: valid.length,
          invalidSecrets: invalid.length,
          missingSecrets: missing.length
        }
      };
    } catch (error) {
      const errorMsg = error instanceof Error ? error.message : String(error);
      logger.error(`[SecretsStatusProvider] Error getting secrets status: ${errorMsg}`);
      return {
        text: "",
        data: { error: errorMsg },
        values: {
          configuredSecrets: 0,
          invalidSecrets: 0,
          missingSecrets: 0
        }
      };
    }
  }
};
var secretsInfoProvider = {
  name: "SECRETS_INFO",
  description: "Provides detailed secret information based on conversation context",
  dynamic: true,
  contexts: ["secrets", "settings"],
  contextGate: { anyOf: ["secrets", "settings"] },
  cacheStable: false,
  cacheScope: "turn",
  roleGate: { minRole: "ADMIN" },
  get: async (runtime2, _message, _state) => {
    const secretsService = runtime2.getService(SECRETS_SERVICE_TYPE);
    if (!secretsService) {
      return { text: "" };
    }
    try {
      const globalSecrets = await secretsService.list({
        level: "global",
        agentId: runtime2.agentId,
        requesterId: runtime2.agentId
      });
      const secretCount = Object.keys(globalSecrets).length;
      if (secretCount === 0) {
        return {
          text: `[Secrets Info]
No secrets configured. User can set secrets by saying things like "Set my OPENAI_API_KEY to sk-..."`
        };
      }
      const lines = ["[Secrets Info]"];
      lines.push(`Total configured secrets: ${secretCount}`);
      const byType = {};
      for (const [key, config] of Object.entries(globalSecrets)) {
        const type = config.type;
        if (!byType[type]) {
          byType[type] = [];
        }
        byType[type].push(key);
      }
      for (const [type, keys2] of Object.entries(byType)) {
        lines.push(`${type}: ${keys2.slice(0, MAX_SECRET_KEYS).join(", ")}`);
      }
      const commonSecrets = [
        "OPENAI_API_KEY",
        "ANTHROPIC_API_KEY",
        "DISCORD_BOT_TOKEN",
        "TELEGRAM_BOT_TOKEN",
        "TWITTER_API_KEY"
      ];
      const missingCommon = commonSecrets.filter((key) => !globalSecrets[key]);
      if (missingCommon.length > 0 && missingCommon.length < commonSecrets.length) {
        lines.push(`Common secrets not set: ${missingCommon.join(", ")}`);
      }
      return {
        text: lines.join(`
`),
        data: {
          secretCount,
          secretTypes: Object.fromEntries(Object.entries(byType).map(([type, keys2]) => [
            type,
            keys2.slice(0, MAX_SECRET_KEYS)
          ]))
        },
        values: {
          secretCount
        }
      };
    } catch (error) {
      const errorMsg = error instanceof Error ? error.message : String(error);
      logger.error(`[SecretsInfoProvider] Error: ${errorMsg}`);
      return {
        text: "",
        data: { error: errorMsg },
        values: { secretCount: 0 }
      };
    }
  }
};

