init_logger2();
async function runInstall({
  runtime: runtime2,
  name,
  source,
  callback
}) {
  const service2 = runtime2.getService("plugin_manager");
  if (!service2) {
    const text3 = "Plugin manager service not available";
    await callback?.({ text: text3 });
    return { success: false, text: text3 };
  }
  if (!name) {
    const text3 = "Specify a plugin name to install (e.g. @elizaos/plugin-discord).";
    await callback?.({ text: text3 });
    return { success: false, text: text3 };
  }
  const prevClone = process.env.PLUGIN_MANAGER_LOCAL_CLONE;
  if (source === "git")
    process.env.PLUGIN_MANAGER_LOCAL_CLONE = "true";
  const result = await service2.installPlugin(name, (progress) => {
    logger.info(`[plugin-manager] install ${name} ${progress.phase}: ${progress.message}`);
  });
  if (source === "git") {
    if (prevClone === undefined)
      delete process.env.PLUGIN_MANAGER_LOCAL_CLONE;
    else
      process.env.PLUGIN_MANAGER_LOCAL_CLONE = prevClone;
  }
  if (!result.success) {
    const text3 = `Failed to install ${name}: ${result.error ?? "unknown error"}`;
    await callback?.({ text: text3 });
    return { success: false, text: text3 };
  }
  const text2 = `Installed ${result.pluginName}@${result.version} at ${result.installPath}` + (result.requiresRestart ? `
Restart required to activate.` : "");
  await callback?.({ text: text2 });
  return {
    success: true,
    text: text2,
    values: {
      mode: "install",
      name: result.pluginName,
      version: result.version,
      installPath: result.installPath
    },
    data: {
      success: result.success,
      pluginName: result.pluginName,
      version: result.version,
      installPath: result.installPath,
      requiresRestart: result.requiresRestart
    }
  };
}

