init_model();
function isLocalProvider(provider) {
  const normalized = provider.toLowerCase();
  if (LOCAL_MODEL_PROVIDERS.includes(normalized)) {
    return true;
  }
  return normalized.includes("ollama") || normalized.includes("lm-studio") || normalized.includes("lmstudio") || normalized.includes("mlx") || normalized.includes("llama.cpp") || normalized.includes("llamacpp") || normalized.includes("eliza-local-inference") || normalized.includes("eliza-device-bridge") || normalized.includes("capacitor-llama") || normalized.includes("eliza-aosp-llama") || normalized === "local";
}
function isLocalHandler(candidate) {
  const declared = candidate.metadata?.local;
  if (typeof declared === "boolean") {
    return declared;
  }
  return isLocalProvider(candidate.provider);
}
var ACTION_MODEL_STRATEGIES = {
  LOCAL: {
    chain: [
      { modelType: ModelType.TEXT_SMALL, providerFilter: isLocalHandler },
      { modelType: ModelType.TEXT_SMALL },
      { modelType: ModelType.TEXT_LARGE }
    ]
  },
  TEXT_SMALL: {
    chain: [
      { modelType: ModelType.TEXT_SMALL },
      { modelType: ModelType.TEXT_LARGE }
    ]
  },
  TEXT_LARGE: {
    chain: [{ modelType: ModelType.TEXT_LARGE }]
  }
};
var ROUTABLE_TEXT_MODEL_TYPES = new Set([
  ModelType.TEXT_NANO,
  ModelType.TEXT_SMALL,
  ModelType.TEXT_MEDIUM,
  ModelType.TEXT_LARGE,
  ModelType.TEXT_MEGA,
  ModelType.RESPONSE_HANDLER,
  ModelType.ACTION_PLANNER,
  ModelType.TEXT_REASONING_SMALL,
  ModelType.TEXT_REASONING_LARGE,
  ModelType.TEXT_COMPLETION
]);
function getActionModelStrategy(modelClass) {
  if (!modelClass) {
    return;
  }
  return ACTION_MODEL_STRATEGIES[modelClass];
}
function maybeReroute(modelClass, requestedModelType) {
  if (!ROUTABLE_TEXT_MODEL_TYPES.has(requestedModelType)) {
    return;
  }
  return getActionModelStrategy(modelClass);
}
function resolveChain(strategy, lookup) {
  const resolved = [];
  const seen = new Set;
  for (const step of strategy.chain) {
    const handlers = lookup(step.modelType);
    if (!handlers || handlers.length === 0) {
      continue;
    }
    for (const handler of handlers) {
      if (step.providerFilter && !step.providerFilter(handler)) {
        continue;
      }
      const key = `${step.modelType}:${handler.provider}`;
      if (seen.has(key)) {
        continue;
      }
      seen.add(key);
      resolved.push({
        handler: handler.handler,
        modelType: step.modelType,
        provider: handler.provider
      });
      break;
    }
  }
  return resolved;
}
function isLowConfidence(result2, threshold) {
  if (threshold === undefined) {
    return false;
  }
  if (!result2 || typeof result2 !== "object") {
    return false;
  }
  const conf = result2.confidence;
  if (typeof conf !== "number") {
    return false;
  }
  return conf < threshold;
}
async function executeChainWithFallback(chain, threshold, invoke) {
  if (chain.length === 0) {
    throw new Error("executeChainWithFallback: chain is empty — no handlers resolved");
  }
  let lastError;
  for (let i10 = 0;i10 < chain.length; i10++) {
    const resolved = chain[i10];
    if (!resolved) {
      continue;
    }
    try {
      const result2 = await invoke(resolved);
      const isLast = i10 === chain.length - 1;
      if (!isLast && isLowConfidence(result2, threshold)) {
        lastError = new Error(`Low-confidence result from ${resolved.modelType} (provider=${resolved.provider}); escalating`);
        continue;
      }
      return result2;
    } catch (err) {
      lastError = err;
    }
  }
  if (lastError instanceof Error) {
    throw lastError;
  }
  throw new Error(`executeChainWithFallback: all ${chain.length} step(s) failed without a thrown error`);
}

