// src/utils/union-find.ts
class UnionFind {
  parent = new Map;
  constructor(initial) {
    if (initial) {
      for (const value of initial) {
        this.add(value);
      }
    }
  }
  add(value) {
    if (!this.parent.has(value)) {
      this.parent.set(value, value);
    }
  }
  has(value) {
    return this.parent.has(value);
  }
  find(value) {
    this.add(value);
    const current = this.parent.get(value) ?? value;
    if (current === value) {
      return current;
    }
    const root = this.find(current);
    this.parent.set(value, root);
    return root;
  }
  union(left, right) {
    const leftRoot = this.find(left);
    const rightRoot = this.find(right);
    if (leftRoot !== rightRoot) {
      this.parent.set(rightRoot, leftRoot);
    }
  }
  groups() {
    const grouped = new Map;
    for (const value of this.parent.keys()) {
      const root = this.find(value);
      const bucket = grouped.get(root);
      if (bucket) {
        bucket.push(value);
      } else {
        grouped.set(root, [value]);
      }
    }
    return grouped;
  }
  componentOf(value) {
    if (!this.parent.has(value)) {
      return [value];
    }
    const root = this.find(value);
    const members = [];
    for (const candidate of this.parent.keys()) {
      if (this.find(candidate) === root) {
        members.push(candidate);
      }
    }
    return members;
  }
}

