function calculateRelationshipStrength({
  interactionCount,
  lastInteractionAt,
  messageQuality = 5,
  relationshipType = "acquaintance",
  sharedConversationWindows = 0
}) {
  const interactionScore = Math.min(interactionCount * 2, 40);
  const sharedConversationScore = Math.min(sharedConversationWindows * 4, 16);
  let recencyScore = 0;
  if (lastInteractionAt) {
    const daysSinceLastInteraction = (Date.now() - new Date(lastInteractionAt).getTime()) / (1000 * 60 * 60 * 24);
    if (daysSinceLastInteraction < 1)
      recencyScore = 30;
    else if (daysSinceLastInteraction < 7)
      recencyScore = 25;
    else if (daysSinceLastInteraction < 30)
      recencyScore = 20;
    else if (daysSinceLastInteraction < 90)
      recencyScore = 10;
    else
      recencyScore = 5;
  }
  const qualityScore = messageQuality / 10 * 20;
  const relationshipBonus = {
    family: 10,
    friend: 8,
    colleague: 6,
    acquaintance: 4,
    unknown: 0
  };
  const totalStrength = interactionScore + recencyScore + qualityScore + sharedConversationScore + (relationshipBonus[relationshipType] ?? 0);
  return Math.max(0, Math.min(100, Math.round(totalStrength)));
}
function toMessageTimestamp(value) {
  if (typeof value === "number" && Number.isFinite(value)) {
    return value;
  }
  if (typeof value === "string" && value.trim().length > 0) {
    const parsed = Number(value);
    if (Number.isFinite(parsed)) {
      return parsed;
    }
  }
  return null;
}
function countSharedConversationWindows(messages, leftEntityId, rightEntityId, windowMs = 1000 * 60 * 60) {
  const relevantMessages = messages.filter((message) => (message.entityId === leftEntityId || message.entityId === rightEntityId) && toMessageTimestamp(message.createdAt) !== null).sort((left, right) => (toMessageTimestamp(left.createdAt) ?? 0) - (toMessageTimestamp(right.createdAt) ?? 0));
  if (relevantMessages.length < 2) {
    return 0;
  }
  const rooms = new Map;
  for (const message of relevantMessages) {
    const roomKey = typeof message.roomId === "string" ? message.roomId : "__shared__";
    if (!rooms.has(roomKey)) {
      rooms.set(roomKey, []);
    }
    rooms.get(roomKey)?.push(message);
  }
  let windowCount = 0;
  for (const roomMessages of rooms.values()) {
    let currentWindowStart = null;
    let seenLeft = false;
    let seenRight = false;
    const flushWindow = () => {
      if (seenLeft && seenRight) {
        windowCount += 1;
      }
      currentWindowStart = null;
      seenLeft = false;
      seenRight = false;
    };
    for (const message of roomMessages) {
      const createdAt = toMessageTimestamp(message.createdAt);
      if (createdAt === null) {
        continue;
      }
      if (currentWindowStart === null || createdAt - currentWindowStart > windowMs) {
        if (currentWindowStart !== null) {
          flushWindow();
        }
        currentWindowStart = createdAt;
      }
      if (message.entityId === leftEntityId) {
        seenLeft = true;
      }
      if (message.entityId === rightEntityId) {
        seenRight = true;
      }
    }
    if (currentWindowStart !== null) {
      flushWindow();
    }
  }
  return windowCount;
}

