// src/runtime/chat-pre-handler-registry.ts
class ChatPreHandlerRegistry {
  byId = new Map;
  register(handler) {
    this.byId.set(handler.id, handler);
  }
  registerMany(handlers) {
    for (const handler of handlers)
      this.register(handler);
  }
  unregister(id2) {
    this.byId.delete(id2);
  }
  clear() {
    this.byId.clear();
  }
  list() {
    return [...this.byId.values()].sort((a10, b10) => (b10.priority ?? 0) - (a10.priority ?? 0));
  }
  get size() {
    return this.byId.size;
  }
  async drain(ctx) {
    for (const handler of this.list()) {
      const result2 = await handler.tryHandle(ctx);
      if (result2)
        return result2;
    }
    return null;
  }
}

// src/runtime/context-hash.ts
function hashString(value) {
  return createHash2("sha256").update(value).digest("hex");
}
function stableStringifyValue(value, seen) {
  if (value === null) {
    return "null";
  }
  const type = typeof value;
  if (type === "string" || type === "number" || type === "boolean") {
    return JSON.stringify(value);
  }
  if (type === "bigint") {
    throw new TypeError("Cannot stable stringify BigInt values as JSON");
  }
  if (type === "undefined" || type === "function" || type === "symbol") {
    return "";
  }
  if (Array.isArray(value)) {
    if (seen.has(value)) {
      throw new TypeError("Cannot stable stringify circular structures");
    }
    seen.add(value);
    const serialized = `[${value.map((item) => {
      const serialized2 = stableStringifyValue(item, seen);
      return serialized2 === "" ? "null" : serialized2;
    }).join(",")}]`;
    seen.delete(value);
    return serialized;
  }
  if (type === "object") {
    if (seen.has(value)) {
      throw new TypeError("Cannot stable stringify circular structures");
    }
    seen.add(value);
    const entries = Object.entries(value).filter(([, entryValue]) => {
      const entryType = typeof entryValue;
      return entryType !== "undefined" && entryType !== "function" && entryType !== "symbol";
    }).sort(([left], [right]) => left.localeCompare(right)).map(([key, entryValue]) => `${JSON.stringify(key)}:${stableStringifyValue(entryValue, seen)}`);
    seen.delete(value);
    return `{${entries.join(",")}}`;
  }
  return JSON.stringify(value);
}
function stableJsonStringify(value) {
  const serialized = stableStringifyValue(value, new WeakSet);
  return serialized === "" ? "null" : serialized;
}
function hashStableJson(value) {
  return hashString(stableJsonStringify(value));
}
function hashPromptSegment(segment) {
  return {
    index: -1,
    hash: hashStableJson({
      content: segment.content,
      id: segment.id,
      label: segment.label,
      metadata: segment.metadata,
      stable: Boolean(segment.stable)
    }),
    contentHash: hashString(segment.content),
    stable: Boolean(segment.stable)
  };
}
function hashPromptSegments(segments) {
  return segments.map((segment, index2) => ({
    ...hashPromptSegment(segment),
    index: index2
  }));
}
function computePrefixHashes(segments) {
  let prefixHash = hashStableJson({ contextPrefix: [] });
  return hashPromptSegments(segments).map((segmentHash, index2) => {
    prefixHash = hashStableJson({
      previousPrefixHash: prefixHash,
      segmentHash: segmentHash.hash
    });
    return {
      index: index2,
      hash: prefixHash,
      segmentHash: segmentHash.hash
    };
  });
}

