var DEFAULT_TEST_CHARACTER = {
  name: "IntegrationTestAgent",
  system: "You are a helpful assistant used for integration testing. Respond concisely and accurately.",
  bio: ["Integration test agent for elizaOS"],
  templates: {},
  messageExamples: [],
  postExamples: [],
  topics: ["testing", "integration"],
  adjectives: [],
  knowledge: [],
  plugins: [],
  secrets: {},
  settings: {}
};
function registerOllamaHandlers(runtime2) {
  const ollamaHandlers = createOllamaModelHandlers();
  for (const [modelType, handler] of Object.entries(ollamaHandlers)) {
    if (handler) {
      runtime2.registerModel(modelType, handler, "ollama");
    }
  }
}
async function createIntegrationTestRuntime(config) {
  const {
    character = {},
    plugins: plugins2 = [],
    databaseAdapter,
    skipInferenceCheck = false,
    initTimeout = 30000
  } = config;
  if (!databaseAdapter) {
    throw new Error(`Integration tests require a database adapter.

` + `Create one using @elizaos/plugin-sql:

` + `  import { createDatabaseAdapter } from '@elizaos/plugin-sql';
` + `  const adapter = createDatabaseAdapter({ dataDir: '/tmp/test' }, agentId);
` + `  await adapter.init();
`);
  }
  const agentId = v4_default();
  const testCharacter = {
    ...DEFAULT_TEST_CHARACTER,
    ...character,
    id: agentId
  };
  logger.info({ src: "integration-test", agentId }, "Creating integration test runtime");
  let inferenceProvider = null;
  if (!skipInferenceCheck) {
    inferenceProvider = await requireInferenceProvider();
  }
  const runtime2 = new AgentRuntime({
    character: testCharacter,
    agentId,
    adapter: databaseAdapter,
    plugins: plugins2
  });
  if (inferenceProvider && inferenceProvider.name === "ollama") {
    registerOllamaHandlers(runtime2);
  }
  const initPromise = runtime2.initialize();
  let timeoutId;
  const timeoutPromise = new Promise((_10, reject) => {
    timeoutId = setTimeout(() => reject(new Error(`Runtime initialization timed out after ${initTimeout}ms`)), initTimeout);
  });
  try {
    await Promise.race([initPromise, timeoutPromise]);
  } finally {
    if (timeoutId) {
      clearTimeout(timeoutId);
    }
  }
  logger.info({ src: "integration-test", agentId }, "Integration test runtime initialized successfully");
  const cleanup = async () => {
    await runtime2.stop();
    logger.debug({ src: "integration-test", agentId }, "Test runtime cleaned up");
  };
  return { runtime: runtime2, agentId, inferenceProvider, cleanup };
}
async function withTestRuntime(testFn, config) {
  const { runtime: runtime2, agentId, cleanup } = await createIntegrationTestRuntime(config);
  try {
    return await testFn(runtime2, agentId);
  } finally {
    await cleanup();
  }
}
// src/testing/loopback.ts
import net2 from "node:net";
var loopbackAvailabilityPromise = null;
function canBindLoopback() {
  if (loopbackAvailabilityPromise) {
    return loopbackAvailabilityPromise;
  }
  loopbackAvailabilityPromise = new Promise((resolve5) => {
    const server = net2.createServer();
    let settled = false;
    const finish = (value) => {
      if (settled) {
        return;
      }
      settled = true;
      server.removeAllListeners();
      resolve5(value);
    };
    server.once("error", () => {
      finish(false);
    });
    server.listen(0, "127.0.0.1", () => {
      server.close(() => finish(true));
    });
  });
  return loopbackAvailabilityPromise;
}
